import math

P = {'step_m': 0.035, 'retreat_m': 0.045, 'vertical_clear_m': 0.12, 'place_above_m': 0.13, 'place_lower_m': 0.03, 'hold_before_open_s': 1.5, 'settle_after_open_s': 1.5, 'correction_step_m': 0.04, 'correction_tolerance_m': 0.004, 'approach_seconds': 2.0, 'retreat_seconds': 2.0, 'waist_pitch_rad': -0.1}
CLOSE = {'left_hand_thumb_0_joint': 0.0, 'left_hand_thumb_1_joint': 0.65, 'left_hand_thumb_2_joint': 0.65, 'left_hand_middle_0_joint': -0.8, 'left_hand_middle_1_joint': -0.6, 'left_hand_index_0_joint': -0.8, 'left_hand_index_1_joint': -0.6}
OPEN = {name: 0.0 for name in CLOSE}
PLACE_ABOVE_M = 0.13
PLACE_LOWER_M = 0.03
WAIST_PITCH = -0.1
APPROACH_S = 2.0


def _walk(start, end, limit=None):
    limit = P['step_m'] if limit is None else limit
    gap = math.dist(start, end)
    count = max(1, math.ceil(gap / limit))
    return [[start[i] + (end[i] - start[i]) * step / count for i in range(3)]
            for step in range(1, count + 1)]


def _move(point, yaw, orientation='yaw', seconds=None):
    return {'op': 'move', 'x': point[0], 'y': point[1], 'z': point[2],
            'yaw': yaw, 'orientation': orientation,
            'seconds': APPROACH_S if seconds is None else seconds}


def _hand(angles, seconds):
    return {'op': 'joints', 'seconds': seconds,
            'targets': [{'joint': name, 'radians': value} for name, value in angles.items()]}


SLOTS = {}


def _place(params, height, slot=None):
    dx, dy = SLOTS[slot] if slot else (0.0, 0.0)
    yaw = params['palm_yaw_rad']
    ox, oy, oz = params['cup_in_palm_m']
    rx = math.cos(yaw) * ox - math.sin(yaw) * oy
    ry = math.sin(yaw) * ox + math.cos(yaw) * oy
    tray = params['tray_floor_m']
    return [tray[0] + dx - rx, tray[1] + dy - ry, tray[2] + height - oz]


def _chosen(observation):
    probe = observation.get('grasp_probe')
    if not probe or not probe.get('yaws'):
        raise ValueError('GRASP_UNREACHABLE: no candidate yaw passes the IK check')
    return probe['yaws'][0]


def grasp_parameters(observation):
    probe = observation.get('grasp_probe')
    tray = observation.get('tray_floor_center_m')
    if not probe or tray is None:
        raise ValueError('grasp_parameters needs grasp_probe and tray_floor_center_m')
    chosen = _chosen(observation)
    return {'palm_yaw_rad': chosen['palm_yaw_rad'],
            'waist_pitch_rad': chosen.get('waist_pitch_rad', WAIST_PITCH),
            'cup_in_palm_m': list(probe['cup_in_palm_m']),
            'tray_floor_m': list(tray)}


def _recenter(observation, params, tolerance, step):
    cups = observation.get('cup_bottoms_m') or []
    if len(cups) != 1:
        return []
    tray = params['tray_floor_m']
    dx, dy = tray[0] - cups[0][0], tray[1] - cups[0][1]
    gap = math.hypot(dx, dy)
    if gap <= tolerance:
        return []
    palm = list(observation['left_palm']['position_m'])
    scale = min(1.0, step / gap)
    point = [palm[0] + dx * scale, palm[1] + dy * scale, palm[2]]
    return [_move(point, params['palm_yaw_rad'], 'keep', 1.5)]


def plan(observation):
    commands = []
    grasp = _chosen(observation)
    params = {'palm_yaw_rad': grasp['palm_yaw_rad'],
              'waist_pitch_rad': grasp.get('waist_pitch_rad', WAIST_PITCH)}
    palm = list(observation['left_palm']['position_m'])
    target = [-0.07, 0.34, 0.09]
    for point in _walk(palm, target):
        commands.append(_move(point, 0.0, 'keep'))
    palm = list(target)
    target = [-0.04, 0.34, 0.3]
    for point in _walk(palm, target):
        commands.append(_move(point, params['palm_yaw_rad'], 'yaw'))
    palm = list(target)
    commands.append({'op': 'joints', 'seconds': 1.0,
                     'targets': [{'joint': k, 'radians': v} for k, v in {'waist_pitch_joint': params['waist_pitch_rad']}.items()]})
    commands.append({'op': 'wait', 'seconds': 1.0})
    target = [-0.04, 0.34, 0.3]
    commands.append({'op': 'move_linear', 'x': target[0], 'y': target[1],
                     'z': target[2], 'yaw': params['palm_yaw_rad'],
                     'orientation': 'yaw',
                     'seconds': 2.0})
    palm = list(target)
    target = grasp['approach_start_xyz_m']
    commands.append({'op': 'move_linear', 'x': target[0], 'y': target[1],
                     'z': target[2], 'yaw': params['palm_yaw_rad'],
                     'orientation': 'yaw',
                     'seconds': 2.0})
    palm = list(target)
    target = grasp['grasp_xyz_m']
    commands.append({'op': 'move_linear', 'x': target[0], 'y': target[1],
                     'z': target[2], 'yaw': params['palm_yaw_rad'],
                     'orientation': 'yaw',
                     'seconds': 2.0})
    palm = list(target)
    commands.append(_hand(CLOSE, 2.0))
    commands.append({'op': 'wait', 'seconds': 0.5})
    return commands

def lift(observation, params):
    commands = []
    palm = list(observation['left_palm']['position_m'])
    target = [palm[0], palm[1], max(palm[2] + P['vertical_clear_m'],
                            _place(params, PLACE_ABOVE_M)[2])]
    for point in _walk(palm, target):
        commands.append(_move(point, params['palm_yaw_rad'], 'keep'))
    palm = list(target)
    target = _place(params, PLACE_ABOVE_M)
    for point in _walk(palm, target):
        commands.append(_move(point, params['palm_yaw_rad'], 'keep'))
    palm = list(target)
    return commands

def correct(observation, params):
    commands = []
    palm = list(observation['left_palm']['position_m'])
    commands.extend(_recenter(observation, params, P['correction_tolerance_m'], P['correction_step_m']))
    return commands

def release(observation, params):
    commands = []
    palm = list(observation['left_palm']['position_m'])
    target = [palm[0], palm[1], _place(params, P['place_lower_m'])[2]]
    for point in _walk(palm, target):
        commands.append(_move(point, params['palm_yaw_rad'], 'keep'))
    palm = list(target)
    commands.append({'op': 'wait', 'seconds': P['hold_before_open_s']})
    commands.append(_hand(OPEN, 2.0))
    commands.append({'op': 'wait', 'seconds': P['settle_after_open_s']})
    for _index in range(2):
        palm = [palm[0], palm[1], palm[2] + P['retreat_m']]
        commands.append(_move(palm, params['palm_yaw_rad'], 'keep'))
    commands.append({'op': 'wait', 'seconds': 1.2})
    commands.append({'op': 'finish'})
    return commands
